                    if c < info['cmin']: info['cmin'] = c
                    if c > info['cmax']: info['cmax'] = c
                    b_h = info['rmax'] - info['rmin'] + 1
                    b_w = info['cmax'] - info['cmin'] + 1

        info['bbox'] = (b_h, b_w)

