    meta_positions = {}
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if not (rmin <= r <= rmax and cmin <= c <= cmax):
                grid_val = grid[r][c]
                if grid_val != background:
                    if grid_val in meta_positions:
                        meta_positions[grid_val].append((r, c))
                    else:
                        meta_positions[grid_val] = [(r, c)]

    # Add neighbor blocks based on meta-pixels
    for block_c, info in block_info.items():
        if block_c not in meta_positions:
